root.css:
.f{font-family:Inter,Arial,sans-serif;color:#f1f2f5;background:#0b0d12;overflow:visible}
.f .c.html{overflow:visible}
.f .c.label{font-size:11px;letter-spacing:1.5px;font-weight:700;color:#9da5b5}
.f .c.textbox,.f .c.textarea{border:1px solid #343a48;border-radius:7px;background:#151923;color:#f5f6f8;padding:11px 13px;font:14px Arial}
.f .c.textbox:focus,.f .c.textarea:focus{outline:2px solid #b6f36b;border-color:#b6f36b}
.f .c.button{background:#b6f36b;color:#11170b;border:0;border-radius:7px;font-weight:800;cursor:pointer}
.f .c.button:hover{filter:brightness(1.08);transform:translateY(-2px)}
.site-header{height:92px;padding:0 64px;display:flex;align-items:center;justify-content:space-between;background:#0b0d12;border-bottom:1px solid #242936}
.brand{display:flex;align-items:center;gap:12px;font-size:14px;font-weight:900;letter-spacing:2px}
.brand-mark{width:34px;height:34px;border-radius:9px;background:#b6f36b;color:#11170b;display:grid;place-items:center;font-size:20px}
.brand-light{color:#81899a;font-weight:500}
.site-header nav{display:flex;gap:34px}
.site-header nav a,.text-link{color:#a9b0bd;text-decoration:none;font-size:13px}
.site-header nav a:hover,.text-link:hover{color:#b6f36b}
.nav-cta{background:#202631;border:1px solid #394151;border-radius:6px;padding:12px 17px;color:#f4f5f7;text-decoration:none;font-size:12px}
.nav-cta b{color:#b6f36b;margin-left:12px}
.hero{height:480px;position:relative;padding:62px 64px;background:radial-gradient(ellipse at 78% 50%,#1a2630 0%,#0b0d12 48%)}
.hero-copy{position:relative;z-index:2;width:58%}
.eyebrow,.section-kicker{font-size:10px;letter-spacing:2px;font-weight:800;color:#b6f36b}
.eyebrow span{display:inline-block;width:7px;height:7px;border-radius:50%;background:#b6f36b;margin-right:10px}
.hero h1{font-size:62px;line-height:1.02;letter-spacing:-3px;margin:24px 0 18px;font-weight:800}
em{font-style:normal;color:#b6f36b}
.hero-copy p{font-size:15px;line-height:1.8;color:#a2aab8;max-width:510px}
.hero-actions{display:flex;align-items:center;gap:26px;margin-top:25px}
.button-primary{display:inline-block;background:#b6f36b;color:#11170b;padding:14px 18px;border-radius:6px;text-decoration:none;font-size:12px;font-weight:800}
.button-primary b{margin-left:15px}
.text-link span{color:#b6f36b;margin-left:8px}
.hero-foot{display:flex;gap:35px;margin-top:40px;font-size:9px;letter-spacing:1.6px;color:#6f7888}
.hero-art{position:absolute;right:50px;top:20px;width:430px;height:430px}
.orbit{position:absolute;border:1px solid #43505c;border-radius:50%;left:50%;top:50%;transform:translate(-50%,-50%) rotate(-25deg)}
.orbit-one{width:390px;height:180px}.orbit-two{width:330px;height:330px;transform:translate(-50%,-50%) rotate(38deg)}.orbit-three{width:250px;height:390px;transform:translate(-50%,-50%) rotate(58deg)}
.core{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:150px;height:150px;border-radius:42px;background:linear-gradient(145deg,#d2ff92,#83bd4c);box-shadow:0 0 90px #a9ef6b44;display:grid;place-items:center;rotate:45deg}
.core-inner{font-size:62px;font-weight:900;color:#17210f;rotate:-45deg}.core-inner span{font-size:23px;vertical-align:top}
.art-tag{position:absolute;font-size:9px;letter-spacing:1.5px;color:#b6f36b;background:#151c20;border:1px solid #43534b;padding:9px 12px;border-radius:4px}
.tag-top{top:45px;right:10px}.tag-bottom{bottom:40px;left:0}
.art-dot{position:absolute;width:9px;height:9px;background:#b6f36b;border-radius:50%;box-shadow:0 0 18px #b6f36b}
.dot-a{top:72px;left:68px}.dot-b{bottom:75px;right:60px}
.stats{height:140px;background:#151a22;border-top:1px solid #2b323e;border-bottom:1px solid #2b323e;display:grid;grid-template-columns:repeat(4,1fr);align-items:center;padding:0 64px}
.stats div{border-right:1px solid #303846;padding-left:35px}.stats div:first-child{padding-left:0}.stats div:last-child{border:0}
.stats strong{display:block;font-size:34px;letter-spacing:-1px}.stats strong span{color:#b6f36b}.stats small{font-size:9px;letter-spacing:1.5px;color:#8791a1}
.intro{height:290px;padding:54px 64px;background:#0e1118}
.intro-main{display:grid;grid-template-columns:1fr 1fr;gap:60px;margin-top:25px}
.intro h2,.section-title h2,.approach h2,.contact-heading h2{font-size:37px;line-height:1.12;letter-spacing:-1.5px;margin:0}
.intro-main p{font-size:13px;line-height:1.8;color:#9ba4b3;margin:0 0 12px}.intro-main .lead{font-size:16px;color:#f0f2f4}
.under-link{color:#b6f36b;font-size:11px;text-decoration:none;font-weight:700}.under-link span{margin-left:10px}
.services{height:420px;padding:48px 64px;background:#151a22}
.section-title{display:flex;justify-content:space-between;align-items:end;margin:18px 0 27px}
.section-title p{width:340px;color:#9ba4b3;font-size:12px;line-height:1.7}
.service-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
.service-grid article{height:220px;padding:19px 21px;background:#1b222d;border:1px solid #303947;border-radius:8px;position:relative}
.service-no{position:absolute;right:18px;top:17px;color:#748091;font-size:10px}
.service-icon{font-size:23px;color:#b6f36b;margin-bottom:10px}
.service-grid h3{font-size:16px;margin:0 0 9px}.service-grid p{font-size:11px;line-height:1.65;color:#9ba4b3;min-height:55px}
.service-grid a{font-size:10px;color:#b6f36b;text-decoration:none;font-weight:700}.service-grid a span{margin-left:8px}
.approach{height:260px;padding:43px 64px;background:#0e1118}
.approach-grid{display:grid;grid-template-columns:1fr 1fr;gap:60px;margin-top:24px}
.steps>div{display:flex;gap:18px;padding:9px 0;border-bottom:1px solid #29313d}
.steps b{font-size:11px;color:#b6f36b}.steps strong{display:block;font-size:12px}.steps small{display:block;color:#8e98a8;font-size:10px;margin-top:4px}
.contact-heading{height:125px;padding:15px 64px 0;background:#151a22}
.contact-heading h2{font-size:27px;display:inline-block;margin:12px 25px 0 0;vertical-align:middle}
.contact-heading p{display:inline-block;max-width:290px;color:#9ba4b3;font-size:11px;line-height:1.6;vertical-align:middle}
.site-footer{height:90px;padding:0 64px;display:flex;align-items:center;justify-content:space-between;background:#090b10;border-top:1px solid #2a303b}
.site-footer>span{font-size:9px;letter-spacing:1.2px;color:#788292}
